exercises.tests:
def test_first_two():
    assert first_two == [10, 20], f"ожидалось [10, 20], получено {first_two}"


def test_last_element():
    assert last_element == 50, f"ожидалось 50, получено {last_element}"


def test_sum_all():
    assert sum_all == 150, f"ожидалось 150, получено {sum_all}"

def test_passed_failed_counts():
    assert passed == 4, f"ожидалось passed=4, получено {passed}"
    assert failed == 3, f"ожидалось failed=3, получено {failed}"


def test_summary_string():
    assert summary == "Passed: 4, Failed: 3", f"получено: {summary}"


def test_last_three_slice():
    assert last_three == [False, False, True], f"ожидалось [False, False, True], получено {last_three}"

def test_has_server_error():
    assert has_server_error is True, "500 есть в списке, has_server_error должен быть True"


def test_first_404_index():
    assert first_404_index == 2, f"первый 404 находится по индексу 2, получено {first_404_index}"


def test_sorted_codes():
    assert sorted_codes == [200, 200, 200, 200, 404, 500], f"получено {sorted_codes}"


def test_original_not_mutated():
    assert status_codes == [200, 200, 404, 200, 500, 200], "sorted() не должен менять исходный список status_codes"

def test_buggy_copy_affects_original():
    assert original_after == [1, 2, 3, 99], f"buggy_copy — та же ссылка, что и original, поэтому .append(99) на buggy_copy виден и в original; получено {original_after}"


def test_real_copy_independent():
    assert real_copy == [1, 2, 3, 99], f"real_copy — независимая копия, в неё тоже должно быть добавлено 99, получено {real_copy}"


def test_original_has_single_99():
    assert original.count(99) == 1, "в original должно оказаться только одно значение 99 — от buggy_copy, а не от real_copy"
